    "parentDoc": "TabBar",
    "usage": {
      "description": "Use TabBar to switch between an app's three to five top-level sections on a phone, each keeping its own state and navigation stack. Keep each section's navigation stack in the app and return it to its root in onReselect.",
      "bestPractices": [
        {
          "guidance": true,
          "description": "Keep every tab visible and the set stable; give each a short label and an outline icon with a filled selectedIcon."
        },
        {
          "guidance": true,
          "description": "Use a badge for something that needs attention in that section, such as unread items, and say what it counts in badgeLabel."
        },
        {
          "guidance": true,
          "description": "Give each tab a panelId naming its section's panel, so assistive technology can associate the two."
        },
        {
          "guidance": true,
          "description": "Disable a tab only while its section cannot open, and keep it in place, so the other tabs do not move."
        },
        {
          "guidance": false,
          "description": "Don't use it for actions, for filters within one screen (use SegmentedControl) or for tabs inside a page (use TabList)."
        }
      ]
    },
